static const fcn22_g_t *fcn22_find(unsigned cp) {
    int lo = 0, hi = (int)FCN22_N - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        unsigned m = fcn22_dir[mid].cp;
        if (m == cp) return &fcn22_dir[mid];
        if (m < cp) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}
static void fcn22_glyph(int x, int y, const fcn22_g_t *g, uint32_t fg) {
    fg = fb_map(fg);
    const unsigned char *bm = fcn22_bits + g->off;
    int gx = x + g->xo, gy = y + g->yo;
    int idx = 0;
    for (int r = 0; r < g->h; r++) {
        for (int c = 0; c < g->w; c++) {
            unsigned a = (idx & 1) ? (bm[idx >> 1] & 0xF) : (bm[idx >> 1] >> 4);
            idx++;
            if (a) fcn_blend(gx + c, gy + r, a, fg);
        }
    }
}
static int fcn22_text(int x, int y, const char *s, uint32_t fg) {
    while (*s) {
        unsigned cp;
        int n = utf8_dec((const unsigned char *)s, &cp);
        const fcn22_g_t *g = fcn22_find(cp);
        if (g) { fcn22_glyph(x, y, g, fg); x += g->adv; }
        else if (cp < 0x80 && cp >= ' ') { x += FCN22_PX / 2; }
        s += n;
    }
    return x;
}
static int fcn22_w(const char *s) {
    int x = 0;
    while (*s) {
        unsigned cp;
        int n = utf8_dec((const unsigned char *)s, &cp);
        const fcn22_g_t *g = fcn22_find(cp);
        x += g ? g->adv : (cp < 0x80 && cp >= ' ' ? FCN22_PX / 2 : 0);
        s += n;
    }
    return x;
}
static void fcn22_center(int cx, int y, const char *s, uint32_t fg) {
    fcn22_text(cx - fcn22_w(s) / 2, y, s, fg);
}

